/// <summary>
/// Bug 394695: [MS-MET] SysMessageProcessorTask.processBundle - Error logging
/// Duplicating std class SysMessageProcessorTaskErrorState as internal
/// Replaced recordArray by message
/// The <c>SysMessageProcessorTaskErrorState</c> class contains information related to the state
/// of message processing during the error.
/// </summary>
final class METSysMessageProcessorTaskErrorState
{
    //private Array recordArray;
    private SysMessage message;
    private SysMessageProcessorMessageLog log;
    private List processedLog;
    private List failedDependencyLog;
    private RecordInsertList recordInsertList;
    private boolean isExceptionDuringMessageProcessing;
    private boolean isExceptionDuringMessageCancellation;

    /*internal Array getRecordArray()
    {
        return recordArray;
    }*/

}

Method.Source:
internal static METSysMessageProcessorTaskErrorState construct(
    //Array                           _recordArray,
    SysMessage                      _message,
    SysMessageProcessorMessageLog   _log,
    List                            _processedLog,
    List                            _failedDependencyLog,
    RecordInsertList                _recordInsertList,
    boolean                         _isExceptionDuringMessageProcessing,
    boolean                         _isExceptionDuringMessageCancellation)
{
    var state = new METSysMessageProcessorTaskErrorState();

    //state.recordArray = _recordArray;
    state.message = _message;
    state.log = _log;
    state.processedLog = _processedLog;
    state.failedDependencyLog = _failedDependencyLog;
    state.recordInsertList = _recordInsertList;
    state.isExceptionDuringMessageProcessing = _isExceptionDuringMessageProcessing;
    state.isExceptionDuringMessageCancellation = _isExceptionDuringMessageCancellation;

    return state;
}
